Task RunMergedDocument()
{
    var document1 = Document
        .Create(container =>
        {
            container.Page(page =>
            {
                page.Content()
                    .Text("Page 1!")
                    .SemiBold().FontSize(36).FontColor(Colors.Blue.Medium);
            });
