namespace QuestPDF.ConformanceTests;

internal class DecorationTests : ConformanceTestBase
{
    protected override Document GetDocumentUnderTest()
    {
        QuestPDF.Settings.EnableDebugging = true;

        return Document
            .Create(document =>
            {
                document.Page(page =>
                {
                    page.Size(600, 975);
                    page.Margin(50);

                    page.Content()
                        .Decoration(decoration =>
                        {
                            decoration.Before()
                                .Column(column =>
                                {
                                    column.Item()
                                        .ShowOnce()
                                        .Height(50)
                                        .Width(200)
                                        .SemanticImage("First page: decoration before")
                                        .Image(Placeholders.Image);

                                    column.Item()
                                        .SkipOnce()
                                        .Text("Second page: decoration before");
                                });

                            decoration
                                .Content()
                                .PaddingVertical(25)
                                .Column(column =>
                                {
                                    column.Spacing(25);

                                    foreach (var i in Enumerable.Range(1, 15))
                                    {
                                        column.Item()
                                            .Width(200)
                                            .Height(50)
                                            .Background(Colors.Grey.Lighten3)
                                            .AlignCenter()
                                            .AlignMiddle()
                                            .Text($"Item {i}");
                                    }
                                });

                            decoration.After()
                                .Column(column =>
                                {
                                    column.Item()
                                        .ShowOnce()
                                        .Height(50)
                                        .Width(200)
                                        .SemanticImage("First page: decoration after")
                                        .Image(Placeholders.Image);

                                    column.Item()
                                        .SkipOnce()
                                        .Text("Second page: decoration after");
                                });
                        });
                });
            });
    }

    protected override SemanticTreeNode? GetExpectedSemanticTree()
    {
        return ExpectedSemanticTree.DocumentRoot(root =>
        {
            root.Child("Figure", figure => figure
                .Alt("First page: decoration before")
                .Attribute("Layout", "BBox", new[] { 50f, 875f, 250f, 925f }));

            foreach (var i in Enumerable.Range(1, 10))
                root.Child("P");

            root.Child("Figure", figure => figure
                .Alt("First page: decoration after")
                .Attribute("Layout", "BBox", new[] { 50f, 50f, 250f, 100f }));

            foreach (var i in Enumerable.Range(1, 5))
                root.Child("P");
        });
    }
}

using QuestPDF.ConformanceTests.TestEngine;
using QuestPDF.Drawing;
using QuestPDF.Elements;
using QuestPDF.Fluent;
using QuestPDF.Infrastructure;

namespace QuestPDF.ConformanceTests;

internal class DynamicTests : ConformanceTestBase
{
    protected override Document GetDocumentUnderTest()
    {
        var imageData = File.ReadAllBytes("Resources/photo.jpeg");

        return Document
            .Create(document =>
            {
                document.Page(page =>
                {
                    page.Margin(60);

                    page.Content()
                        .PaddingVertical(30)
                        .Column(column =>
                        {
                            column.Spacing(25);

                            column.Item().SemanticHeader1().Text("Conformance Test: Lazy");

                            column.Item().SemanticHeader2().Text("Before lazy");

                            foreach (var i in Enumerable.Range(0, 10))
                                column.Item().Dynamic(new DynamicComponent(i));

                            column.Item().SemanticHeader2().Text("After lazy");
                        });
                });
            });
    }

    protected override SemanticTreeNode? GetExpectedSemanticTree()
    {
        return ExpectedSemanticTree.DocumentRoot(root =>
        {
            root.Child("H1", h1 => h1.Alt("Conformance Test: Lazy"));
            root.Child("H2", h2 => h2.Alt("Before lazy"));

            foreach (var i in Enumerable.Range(0, 10))
            {
                root.Child("Art", art =>
                {
                    art.Child("H3", h3 => h3.Alt($"Article {i}"));

                    foreach (var j in Enumerable.Range(0, 10))
                    {
                        art.Child("P");
                    }
                });
            }

            root.Child("H2", h2 => h2.Alt("After lazy"));
        });
    }

    internal class DynamicComponent(int index) : IDynamicComponent
    {
        public DynamicComponentComposeResult Compose(DynamicContext context)
        {
            var result = context.CreateElement(container =>
            {
                container.SemanticArticle().Column(column =>
                {
                    column.Item().SemanticHeader3().Text($"Article {index}").Bold();

                    foreach (var j in Enumerable.Range(0, 10))
                    {
                        column.Item().Text($"{index} - {j}");
                    }
                });
            });

            if (result.Size.Height > context.AvailableSize.Height)
            {
                return new DynamicComponentComposeResult
                {
                    Content = context.CreateElement(container => { }),
                    HasMoreContent = true
                };
            }

            return new DynamicComponentComposeResult
            {
                Content = result,
                HasMoreContent = false
            };
        }
    }
}

