using UnityEngine;

public class AerodynamicsSimulation : MonoBehaviour
{
    [SerializeField] private float m_ZeroLiftSpeed = 300;
    [SerializeField] private float m_PitchEffect = 1f;
    [SerializeField] private float m_AerodynamicEffect = 0.02f;
    [SerializeField] private float m_AirBrakesEffect = 3f;
    [SerializeField] private float m_ThrottleChangeSpeed = 0.3f;
    [SerializeField] private float m_DragIncreaseFactor = 0.001f;
    [SerializeField] private float m_torqueFactor = 0.1f;

    public (float lift, float drag, float torque) CalculateAerodynamics(float speed, float throttleInput, float pitchInput, float airBrakeInput)
    {
        float lift = (speed <= m_ZeroLiftSpeed) ? 0 : m_AerodynamicEffect * speed * speed - m_ZeroLiftSpeed * m_ZeroLiftSpeed;
        float drag = m_DragIncreaseFactor * speed * speed + m_AirBrakesEffect * airBrakeInput;
        float torque = throttleInput * m_torqueFactor - pitchInput * m_PitchEffect;

        return (lift, drag, torque);
    }
}

