using System;
using System.Xml;

class Program
{
    static void Main()
    {
        string filePath = "recipes.xml"; // Path to the XML file
        string targetIngredient = "tomato"; // The ingredient to search for in the recipes

        using (XmlReader xmlReader = XmlReader.Create(filePath))
        {
            while (xmlReader.Read())
            {
                if (xmlReader.NodeType == XmlNodeType.Element && xmlReader.Name == "recipe")
                {
                    string recipeName = xmlReader.GetAttribute("name");
                    bool containsTargetIngredient = false;

                    // Navigate to the ingredients section of the recipe
                    while (xmlReader.Read())
                    {
                        if (xmlReader.NodeType == XmlNodeType.Element && xmlReader.Name == "ingredient")
                        {
                            string ingredientName = xmlReader.ReadElementContentAsString();
                            if (ingredientName.ToLower().Contains(targetIngredient))
                            {
                                containsTargetIngredient = true;
                                break;
                            }
                        }
                        if (xmlReader.NodeType == XmlNodeType.EndElement && xmlReader.Name == "recipe")
                        {
                            break;
                        }
                    }

                    if (containsTargetIngredient)
                    {
                        Console.WriteLine(recipeName);
                    }
                }
            }
        }
    }
}

