public static int CalculateMedian(int[] numbers)
{
    if (numbers.Length == 0)
    {
        return 0;
    }

    if (numbers.Length == 1)
    {
        return numbers[0];
    }

    int[] sortedNumbers = MergeSort(numbers);

    int middleIndex = sortedNumbers.Length / 2;

    if (sortedNumbers.Length % 2 == 0)
    {
        return (sortedNumbers[middleIndex] + sortedNumbers[middleIndex - 1]) / 2;
    }
    else
    {
        return sortedNumbers[middleIndex];
    }
}

public static int[] MergeSort(int[] numbers)
{
    if (numbers.Length <= 1)
    {
        return numbers;
    }

    int middleIndex = numbers.Length / 2;
    int[] left = new int[middleIndex];
    int[] right = new int[numbers.Length - middleIndex];

    Array.Copy(numbers, 0, left, 0, middleIndex);
    Array.Copy(numbers, middleIndex, right, 0, numbers.Length - middleIndex);

    left = MergeSort(left);
    right = MergeSort(right);

    return Merge(left, right);
}

public static int[] Merge(int[] left, int[] right)
{
    int[] merged = new int[left.Length + right.Length];
    int i = 0;
    int j = 0;
    int k = 0;

    while (i < left.Length && j < right.Length)
    {
        if (left[i] <= right[j])
        {
            merged[k] = left[i];
            i++;
        }
        else
        {
            merged[k] = right[j];
            j++;
        }

        k++;
    }

    while (i < left.Length)
    {
        merged[k] = left[i];
        i++;
        k++;
    }

    while (j < right.Length)
    {
        merged[k] = right[j];
        j++;
        k++;
    }

    return merged;
}

