using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class ControlInformationExtractor
{
    public static Dictionary<string, string> ExtractControlInformation(string codeBehindFileContent)
    {
        Dictionary<string, string> controlInformation = new Dictionary<string, string>();

        // Regular expression pattern to match the control declarations
        string pattern = @"(?<=///\s*<summary>\s*).*control\.\s*<\/summary>\s*<remarks>\s*Auto-generated field\.\s*To modify move field declaration from designer file to code-behind file\.\s*<\/remarks>\s*protected\s*global::(?<ControlType>[\w\.]+)\s*(?<ControlName>[\w]+);";

        // Match control declarations using regular expression
        MatchCollection matches = Regex.Matches(codeBehindFileContent, pattern);

        // Extract control information from matches
        foreach (Match match in matches)
        {
            string controlType = match.Groups["ControlType"].Value;
            string controlName = match.Groups["ControlName"].Value;
            controlInformation[controlName] = controlType;
        }

        return controlInformation;
    }
}

using System;
using System.Runtime.CompilerServices;

public static class Extractor
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ref ushort u16<T>(in T src, int offset)
    {
        unsafe
        {
            fixed (T* ptr = &src)
            {
                return ref *(ushort*)((byte*)ptr + offset);
            }
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ushort u16(ReadOnlySpan<byte> src)
    {
        if (src.Length < 2)
        {
            throw new ArgumentException("Source span must contain at least 2 bytes for extracting a 16-bit unsigned integer.");
        }
        return (ushort)(src[0] | (src[1] << 8));
    }
}

