using System;
using System.Collections.Generic;
using System.Text;

public class IdentityCodeGenerator
{
    private HashSet<string> usedCodes;

    public IdentityCodeGenerator()
    {
        usedCodes = new HashSet<string>();
    }

    public string GenerateIdentityCode()
    {
        const int MaxIdentityCodeLength = 14;
        const string Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        Random random = new Random();
        StringBuilder codeBuilder = new StringBuilder(MaxIdentityCodeLength);
        string newCode;

        do
        {
            codeBuilder.Clear();
            for (int i = 0; i < MaxIdentityCodeLength; i++)
            {
                codeBuilder.Append(Chars[random.Next(Chars.Length)]);
            }
            newCode = codeBuilder.ToString();
        } while (usedCodes.Contains(newCode));

        usedCodes.Add(newCode);
        return newCode;
    }
}

