            results[i] = SearchDatabase(requests[i].Query, database);
        }
        return results;
    }

    private static string SearchDatabase(string query, string database)
    {
        string[] sentences = database.Split(new char[] { '.' }, StringSplitOptions.RemoveEmptyEntries);
        foreach (string sentence in sentences)
        {
            if (sentence.ToLower().Contains(query.ToLower()))
            {
                return sentence.Trim();
            }
        }
        return string.Empty;
    }
}

