using Newtonsoft.Json;
using System.Security.Cryptography;
using System.Text;

public class JsonSigner
{
    public string SignAndSerialize(object jsonObject, string key)
    {
        string serializedJson = JsonConvert.SerializeObject(jsonObject, Formatting.None);
        string signedString = SignString(serializedJson, key);
        return signedString;
    }

    private string SignString(string input, string key)
    {
        using (HMACSHA256 hmac = new HMACSHA256(Encoding.UTF8.GetBytes(key)))
        {
            byte[] hashValue = hmac.ComputeHash(Encoding.UTF8.GetBytes(input));
            return Convert.ToBase64String(hashValue);
        }
    }
}

