using System;
using System.Collections.Generic;
using Basketee.API.Models;

namespace Basketee.API.ServicesLib.Services.Helpers
{
    public class DriverHelper
    {
        public double CalculateTotalDistance(List<Order> orderHistory)
        {
            double totalDistance = 0;

            for (int i = 0; i < orderHistory.Count - 1; i++)
            {
                totalDistance += CalculateDistance(orderHistory[i], orderHistory[i + 1]);
            }

            return totalDistance;
        }

        private double CalculateDistance(Order start, Order end)
        {
            const double earthRadiusKm = 6371;

            double dLat = DegreeToRadian(end.PickupLatitude - start.PickupLatitude);
            double dLon = DegreeToRadian(end.PickupLongitude - start.PickupLongitude);

            double a = Math.Sin(dLat / 2) * Math.Sin(dLat / 2) +
                       Math.Cos(DegreeToRadian(start.PickupLatitude)) * Math.Cos(DegreeToRadian(end.PickupLatitude)) *
                       Math.Sin(dLon / 2) * Math.Sin(dLon / 2);

            double c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));
            double distance = earthRadiusKm * c;

            return distance;
        }

        private double DegreeToRadian(double angle)
        {
            return Math.PI * angle / 180.0;
        }
    }
}

