Write a function or method `ExtractNamespaces` that takes a string `code` as input and returns a list of unique namespaces used in the code.

code:
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class NamespaceResolver
{
    public List<string> ExtractNamespaces(string code)
    {
        List<string> namespaces = new List<string>();

        // Regular expression to match namespace declarations and usages
        Regex namespaceRegex = new Regex(@"\bnamespace\s+([a-zA-Z_][a-zA-Z0-9_.]*)\b");
        Regex usingRegex = new Regex(@"\busing\s+([a-zA-Z_][a-zA-Z0-9_.]*)\b");

        // Match namespace declarations
        MatchCollection namespaceMatches = namespaceRegex.Matches(code);
        foreach (Match match in namespaceMatches)
        {
            string namespaceName = match.Groups[1].Value;
            if (!namespaces.Contains(namespaceName))
            {
                namespaces.Add(namespaceName);
            }
        }

        // Match using statements
        MatchCollection usingMatches = usingRegex.Matches(code);
        foreach (Match match in usingMatches)
        {
            string namespaceName = match.Groups[1].Value;
            if (!namespaces.Contains(namespaceName))
            {
                namespaces.Add(namespaceName);
            }
        }

        return namespaces;
    }
}

