using System;
using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

public class CspOptions
{
    public string HeaderValue { get; set; }
    public string ReportingGroupJson { get; set; }
}

public class CspMiddleware
{
    private readonly RequestDelegate next;
    private readonly string headerValue;
    private readonly string reportingGroupJson;

    public CspMiddleware(RequestDelegate next, CspOptions options)
    {
        if (options == null)
            throw new ArgumentNullException(nameof(options));

        this.next = next;
        this.headerValue = options.HeaderValue;
        this.reportingGroupJson = options.ReportingGroupJson;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Add logic to inspect incoming request and add CSP headers to the response
        AddCspHeaders(context.Response);

        // Call the next middleware in the pipeline
        await next(context);
    }

    private void AddCspHeaders(HttpResponse response)
    {
        // Add CSP headers to the response based on the configuration
        response.Headers.Add("Content-Security-Policy", headerValue);
        response.Headers.Add("Report-To", reportingGroupJson);
    }
}

using System;
using System.Collections.Generic;
using System.Xml;

public class XmlDataExtractor
{
    public Dictionary<string, string> ExtractNonZeroSerializedData(string filePath)
    {
        Dictionary<string, string> extractedData = new Dictionary<string, string>();

        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(filePath);

            XmlNodeList paramNodes = xmlDoc.SelectNodes("//hkparam");

            foreach (XmlNode paramNode in paramNodes)
            {
                string paramName = paramNode.Attributes["name"].Value;
                string paramValue = GetNonZeroSerializedValue(paramNode);

                if (!string.IsNullOrEmpty(paramValue))
                {
                    extractedData[paramName] = paramValue;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error occurred while extracting data: " + ex.Message);
        }

        return extractedData;
    }

    private string GetNonZeroSerializedValue(XmlNode node)
    {
        string value = string.Empty;

        foreach (XmlNode childNode in node.ChildNodes)
        {
            if (childNode.Name == "hkparam")
            {
                string childValue = GetNonZeroSerializedValue(childNode);
                if (!string.IsNullOrEmpty(childValue))
                {
                    value = childValue;
                    break;
                }
            }
            else if (childNode.Name == "serializedValue" && !string.IsNullOrEmpty(childNode.InnerText))
            {
                value = childNode.InnerText;
                break;
            }
        }

        return value;
    }
}

