            return context.SerializeToJson(obj);
        }
        else
        {
            throw new InvalidOperationException("Unsupported serialization target");
        }
    }

    public object DeserializeObject(string serialized)
    {
        if (target == SerializerTarget.Binary)
        {
            byte[] bytes = Convert.FromBase64String(serialized);
            using (MemoryStream memoryStream = new MemoryStream(bytes))
            {
                BinaryFormatter binaryFormatter = new BinaryFormatter();
                return binaryFormatter.Deserialize(memoryStream);
            }
        }
        else if (target == SerializerTarget.Json)
        {
            // Assuming the object can be deserialized from JSON using the context
