using System;
using System.Collections.Generic;
using System.Security.Cryptography;

namespace Hateblo
{
    /// <summary>
    /// Manages user authentication information for WSEE authentication.
    /// </summary>
    public class AuthenticationManager
    {
        private Dictionary<string, string> userAuthInfo; // Stores user authentication information

        public AuthenticationManager()
        {
            userAuthInfo = new Dictionary<string, string>();
        }

        // Add user authentication information
        public void AddUserAuthInfo(string username, string authToken)
        {
            // Store the authentication token securely using hashing
            string hashedToken = HashToken(authToken);
            userAuthInfo[username] = hashedToken;
        }

        // Remove user authentication information
        public void RemoveUserAuthInfo(string username)
        {
            if (userAuthInfo.ContainsKey(username))
            {
                userAuthInfo.Remove(username);
            }
        }

        // Validate user authentication information
        public bool ValidateUserAuthInfo(string username, string authToken)
        {
            if (userAuthInfo.ContainsKey(username))
            {
                string storedHashedToken = userAuthInfo[username];
                string inputHashedToken = HashToken(authToken);
                return storedHashedToken == inputHashedToken;
            }
            return false;
        }

        // Hash the authentication token using SHA256
        private string HashToken(string token)
        {
            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] hashedBytes = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(token));
                return BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
            }
        }
    }
}

