You are tasked with implementing a program that counts the frequency of each character in a given input string and returns the characters along with their respective counts in descending order of frequency. For example, given the input string "abracadabra", the program should return the following output: "a: 5, b: 2, r: 2, c: 1, d: 1". If there are characters with the same frequency, they should be ordered alphabetically. The program should ignore case, so 'A' and 'a' should be considered the same character.

You are provided with the following code snippet to start with:
```csharp
foreach (char c in Input.inputString)
{
    // Your code here
}
```

code:
public string CountCharacterFrequency(string inputString)
{
    Dictionary<char, int> charFrequency = new Dictionary<char, int>();

    // Convert the input string to lowercase to ignore case
    inputString = inputString.ToLower();

    // Count the frequency of each character
    foreach (char c in inputString)
    {
        if (char.IsLetter(c))
        {
            if (charFrequency.ContainsKey(c))
            {
                charFrequency[c]++;
            }
            else
            {
                charFrequency[c] = 1;
            }
        }
    }

    // Sort the characters by frequency in descending order, then alphabetically
    var sortedCharFrequency = charFrequency.OrderByDescending(pair => pair.Value)
                                           .ThenBy(pair => pair.Key)
                                           .ToDictionary(pair => pair.Key, pair => pair.Value);

    // Construct the output string
    string output = "";
    foreach (var entry in sortedCharFrequency)
    {
        output += $"{entry.Key}: {entry.Value}, ";
    }

    // Remove the trailing comma and space
    output = output.TrimEnd(' ', ',');

    return output;
}

