using System;
using System.Security.Cryptography;
using System.Text;

public class Block
{
    public uint BlockNumber { get; set; }
    public string Data { get; set; }
    public string PreviousBlockHash { get; set; }
    public string BlockHash { get; set; }
}

public class BlockchainVerifier
{
    public static bool VerifyBlockchain(Block[] blockchain)
    {
        for (int i = 1; i < blockchain.Length; i++)
        {
            var previousBlock = blockchain[i - 1];
            var currentBlock = blockchain[i];

            if (currentBlock.PreviousBlockHash != CalculateHash(previousBlock))
            {
                return false;
            }
        }
        return true;
    }

    private static string CalculateHash(Block block)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            string data = $"{block.BlockNumber}-{block.Data}-{block.PreviousBlockHash}";
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(data));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                builder.Append(hashBytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }
}

