        List<string> validationResults = ValidateInput(value, memberName);
        errorSummaryByColumnName[memberName] = validationResults;
    }

    private List<string> ValidateInput<T>(T value, string memberName)
    {
        List<string> validationErrors = new List<string>();
        if (string.IsNullOrEmpty(value.ToString()))
        {
            validationErrors.Add($"{memberName} cannot be empty.");
        }
        return validationErrors;
    }

    public bool HasValidationErrors(string memberName)
    {
        return errorSummaryByColumnName.ContainsKey(memberName) && errorSummaryByColumnName[memberName].Any();
    }
}

