using System;
using System.Collections.Generic;
using System.Linq;

public class Transaction
{
    public string SenderAddress { get; set; }
    public List<To> Tos { get; set; }
}

public class To
{
    public string Address { get; set; }
    public decimal Value { get; set; }
}

public class TransactionProcessor
{
    public Dictionary<string, decimal> CalculateTotalSentBySender(List<Transaction> transactions)
    {
        Dictionary<string, decimal> totalSentBySender = new Dictionary<string, decimal>();

        foreach (var transaction in transactions)
        {
            if (totalSentBySender.ContainsKey(transaction.SenderAddress))
            {
                totalSentBySender[transaction.SenderAddress] += transaction.Tos.Sum(to => to.Value);
            }
            else
            {
                totalSentBySender[transaction.SenderAddress] = transaction.Tos.Sum(to => to.Value);
            }
        }

        return totalSentBySender;
    }
}

