        _requestCount++;
    }

    public TimeSpan CalculateAverageResponseTime()
    {
        if (_requestCount == 0)
        {
            return TimeSpan.Zero; // No requests made, average response time is zero.
        }

        TimeSpan totalResponseTime = TimeSpan.Zero;
        foreach (var result in _requestResults)
        {
            totalResponseTime += result.ResponseTime;
        }

        return TimeSpan.FromTicks(totalResponseTime.Ticks / _requestCount);
    }
}

