using System;
using System.Text.RegularExpressions;

public class PublicMethodCounter
{
    public int CountPublicMethods(string classCode)
    {
        int publicMethodCount = 0;

        // Extract the "Public Methods" region content using regex
        Match publicMethodsMatch = Regex.Match(classCode, @"#region Public Methods(.*?)#endregion", RegexOptions.Singleline);

        if (publicMethodsMatch.Success)
        {
            string publicMethodsContent = publicMethodsMatch.Groups[1].Value;

            // Count the occurrences of "public void" within the "Public Methods" region
