            _instance = go.AddComponent<PoolManager>();

            foreach (GameObject prefab in prefabs)
            {
                _instance.CreatePool(prefab, initialSize);
            }
        }
    }

    private void CreatePool(GameObject prefab, int initialSize)
    {
        string key = prefab.name;
        if (!objectPool.ContainsKey(key))
        {
            objectPool[key] = new Queue<GameObject>();

            for (int i = 0; i < initialSize; i++)
            {
                GameObject obj = Instantiate(prefab, Vector3.zero, Quaternion.identity);
                obj.SetActive(false);
                objectPool[key].Enqueue(obj);
            }
        }
    }

    public static GameObject Spawn(GameObject prefab, Vector3 position, Quaternion rotation)
    {
        string key = prefab.name;
        if (_instance.objectPool.ContainsKey(key) && _instance.objectPool[key].Count > 0)
        {
            GameObject obj = _instance.objectPool[key].Dequeue();
            obj.transform.position = position;
            obj.transform.rotation = rotation;
            obj.SetActive(true);
            return obj;
        }
        else
        {
            Debug.LogWarning("No available objects in the pool for " + key);
            return null;
        }
    }

    public static void Despawn(GameObject obj, float time)
    {
        _instance.StartCoroutine(_instance.DespawnCoroutine(obj, time));
    }

    private IEnumerator DespawnCoroutine(GameObject obj, float time)
    {
        yield return new WaitForSeconds(time);
        obj.SetActive(false);
        objectPool[obj.name].Enqueue(obj);
    }
}

