    {
        private Node top;

        public void Push(int value)
        {
            Node newNode = new Node(value, top);
            top = newNode;
        }

        public int Pop()
        {
            if (IsEmpty())
            {
                throw new InvalidOperationException("Stack is empty");
            }
            int value = top.Value;
            top = top.Next;
            return value;
        }

        public int Peek()
        {
            if (IsEmpty())
            {
                throw new InvalidOperationException("Stack is empty");
            }
            return top.Value;
        }

        public bool IsEmpty()
        {
            return top == null;
        }
    }
}

