code:
public async Task<List<UserDto>> GetRecommendedUsers(int pageNumber, int pageSize, Expression<Func<User, bool>> filter = null)
{
    var query = _userRepository.GetRecommendedUsers();

    if (filter != null)
    {
        query = query.Where(filter);
    }

    var totalUsers = await query.CountAsync();
    var totalPages = (int)Math.Ceiling((double)totalUsers / pageSize);

    if (pageNumber < 1)
    {
        pageNumber = 1;
    }
    else if (pageNumber > totalPages)
    {
        pageNumber = totalPages;
    }

    var users = await query.Skip((pageNumber - 1) * pageSize)
                          .Take(pageSize)
                          .ToListAsync();

    return _mapper.Map<List<UserDto>>(users);
}

