public static class MethodCallCounter
{
    private static Dictionary<Type, int> callCount = new Dictionary<Type, int>();

    public static void RecordCall<THandler>(Expression<Action<THandler>> method)
    {
        var methodCallExpression = (MethodCallExpression)method.Body;
        var handlerType = typeof(THandler);
        var messageType = methodCallExpression.Arguments[0].Type;

        var key = $"{handlerType.Name}_{messageType.Name}";

        if (callCount.ContainsKey(key))
        {
            callCount[key]++;
        }
        else
        {
            callCount[key] = 1;
        }
    }

    public static int GetCallCount<THandler, TMessage>()
    {
        var key = $"{typeof(THandler).Name}_{typeof(TMessage).Name}";
        return callCount.ContainsKey(key) ? callCount[key] : 0;
    }
}

