using System.Collections.Generic;
using UnityEngine;

public class DogamDetail : MonoBehaviour
{
    private static DogamDetail _instance = null;
    public static DogamDetail instance
    {
        get
        {
            if (_instance == null)
            {
                _instance = new DogamDetail();
            }
            return _instance;
        }
    }

    private Dictionary<string, string> cachedResponses = new Dictionary<string, string>();

    public void CacheResponse(string url, string response)
    {
        if (!cachedResponses.ContainsKey(url))
        {
            cachedResponses.Add(url, response);
        }
        else
        {
            cachedResponses[url] = response;
        }
    }

    public string GetCachedResponse(string url)
    {
        if (cachedResponses.ContainsKey(url))
        {
            return cachedResponses[url];
        }
        return null;
    }
}

