public class TestCaseExtractor
{
    public static (object[] parameters, object expectedResult) ExtractTestCaseInfo(string testCaseAttribute)
    {
        string pattern = @"\[TestCase\(([^)]+),\s*ExpectedResult\s*=\s*([^)]+)\)\]";
        Match match = Regex.Match(testCaseAttribute, pattern);

        if (match.Success)
        {
            string parametersStr = match.Groups[1].Value;
            string expectedResultStr = match.Groups[2].Value;

            string[] parametersArr = parametersStr.Split(',');
            object[] parameters = new object[parametersArr.Length];
            for (int i = 0; i < parametersArr.Length; i++)
            {
                parameters[i] = Convert.ChangeType(parametersArr[i].Trim(), typeof(object));
            }

            object expectedResult = Convert.ChangeType(expectedResultStr.Trim(), typeof(object));

            return (parameters, expectedResult);
        }
        else
        {
            return (null, null);
        }
    }
}

