public class JointProcessor
{
    public float CalculateAverageJointDistance(JointData jointData)
    {
        float totalDistance = 0;
        int pairCount = 0;

        for (int i = 0; i < jointData.joints.Length; i++)
        {
            for (int j = i + 1; j < jointData.joints.Length; j++)
            {
                float distance = CalculateDistance(jointData.joints[i], jointData.joints[j]);
                totalDistance += distance;
                pairCount++;
            }
        }

        return totalDistance / pairCount;
    }

    private float CalculateDistance(Vector3 joint1, Vector3 joint2)
    {
        float dx = joint2.x - joint1.x;
        float dy = joint2.y - joint1.y;
        float dz = joint2.z - joint1.z;
        return (float)Math.Sqrt(dx * dx + dy * dy + dz * dz);
    }
}

