    {
        public int data;
        public Node next;
        public Node(int data)
        {
            this.data = data;
            this.next = null;
        }
    }

    private Node head;  // Points to the first node in the queue
    private Node tail;  // Points to the last node in the queue

    // Constructor to initialize an empty queue
    public QueueManager()
    {
        head = null;
        tail = null;
    }

    // Method to add an integer to the end of the queue
    public void Enqueue(int value)
    {
        Node newNode = new Node(value);
        if (tail == null)
        {
            head = newNode;
            tail = newNode;
        }
        else
        {
            tail.next = newNode;
            tail = newNode;
        }
    }

    // Method to remove the integer at the front of the queue and return it
    public int Dequeue()
    {
        if (head == null)
        {
            throw new InvalidOperationException("Queue is empty");
        }
        int value = head.data;
        head = head.next;
        if (head == null)
        {
            tail = null;
        }
        return value;
    }

    // Method to return the integer at the front of the queue without removing it
    public int Peek()
    {
        if (head == null)
        {
            throw new InvalidOperationException("Queue is empty");
        }
        return head.data;
    }

    // Method to check if the queue is empty
    public bool IsEmpty()
    {
        return head == null;
    }
