public class TaskManager
{
    private List<Task> tasks = new List<Task>();

    // Add an asynchronous task to the list of managed tasks
    public void AddTask(Task task)
    {
        tasks.Add(task);
    }

    // Start the execution of all the added tasks concurrently
    public async void StartTasks()
    {
        await Task.WhenAll(tasks);
        OnAllTasksCompleted();
    }

    // Event raised when all the added tasks have completed their execution
    public event EventHandler AllTasksCompleted;

    // Method to raise the AllTasksCompleted event
    protected virtual void OnAllTasksCompleted()
    {
        AllTasksCompleted?.Invoke(this, EventArgs.Empty);
    }

    // Remove all the tasks from the list of managed tasks
    public void ClearTasks()
    {
        tasks.Clear();
    }
}

