using System;
using System.Collections.Generic;
using System.Linq;

public class OrderBook
{
    private List<Order> buyOrders;
    private List<Order> sellOrders;

    public OrderBook()
    {
        buyOrders = new List<Order>();
        sellOrders = new List<Order>();
    }

    public void AddOrder(Order order)
    {
        if (order.Type == OrderType.Buy)
        {
            AddToOrderList(order, buyOrders);
        }
        else
        {
            AddToOrderList(order, sellOrders);
        }
    }

    private void AddToOrderList(Order order, List<Order> orderList)
    {
        var existingOrder = orderList.FirstOrDefault(o => o.Price == order.Price);
        if (existingOrder != null)
        {
            existingOrder.Quantity += order.Quantity;
        }
        else
        {
            orderList.Add(order);
        }
    }

    public void RemoveOrder(Order order)
    {
        if (order.Type == OrderType.Buy)
        {
            buyOrders.Remove(order);
        }
        else
        {
            sellOrders.Remove(order);
        }
    }

    public (decimal, decimal) GetBestBid()
    {
        if (buyOrders.Count == 0)
        {
            return (0, 0);
        }
        var bestBid = buyOrders.OrderByDescending(o => o.Price).First();
        return (bestBid.Price, bestBid.Quantity);
    }

    public (decimal, decimal) GetBestAsk()
    {
        if (sellOrders.Count == 0)
        {
            return (0, 0);
        }
        var bestAsk = sellOrders.OrderBy(o => o.Price).First();
        return (bestAsk.Price, bestAsk.Quantity);
    }
}

