private static long sumListWork(bool allowRepetitions, int workingBase, int[] numbers)
{
    // Base case: If the numbers array is empty, return 0
    if (numbers.Length == 0) {
        return 0;
    }

    // Initialize a variable to store the sum
    long sum = 0;

    // Create a helper function to calculate the power of a number
    Func<int, int, long> power = (baseNum, exponent) => {
        long result = 1;
        for (int i = 0; i < exponent; i++) {
            result *= baseNum;
        }
        return result;
    };

    // Create a recursive function to calculate the sum based on the conditions
    Action<int, long, int[]> calculateSum = (currentIndex, currentSum, remainingNumbers) => {
        // Base case: If currentIndex reaches the end of the numbers array, add the currentSum to the total sum
        if (currentIndex == remainingNumbers.Length) {
            sum += currentSum;
            return;
        }

        // Calculate the sum with repetitions allowed
        if (allowRepetitions) {
            for (int i = 0; i <= workingBase; i++) {
                calculateSum(currentIndex + 1, currentSum + (power(workingBase, currentIndex) * i), remainingNumbers);
            }
        }
        // Calculate the sum without repetitions
        else {
            for (int i = 0; i < remainingNumbers.Length; i++) {
                int[] newRemainingNumbers = remainingNumbers.Take(i).Concat(remainingNumbers.Skip(i + 1)).ToArray();
                calculateSum(currentIndex + 1, currentSum + (power(workingBase, currentIndex) * remainingNumbers[i]), newRemainingNumbers);
            }
        }
    };

    // Start the recursive calculation with initial values
    calculateSum(0, 0, numbers);

    return sum;
}

