        {
            new Book { Id = 1, Title = "The Great Gatsby", Author = "F. Scott Fitzgerald", Genre = "Fiction" },
            new Book { Id = 2, Title = "To Kill a Mockingbird", Author = "Harper Lee", Genre = "Fiction" }
        };

        // GET /api/books
        public IHttpActionResult GetBooks()
        {
            return Ok(_books);
        }

