using System.Globalization;
using System.Threading;
using System.Threading.Tasks;

public static class AsyncHelper
{
    private static readonly TaskFactory _myTaskFactory = new TaskFactory(CancellationToken.None,
        TaskCreationOptions.None, TaskContinuationOptions.None, TaskScheduler.Default);

    /// <summary>
    /// Calls an asynchronous method synchronously.
    /// </summary>
    /// <typeparam name="TResult">The type of the result.</typeparam>
    /// <param name="func">A reference to an asynchronous method.</param>
    /// <returns>Returns an instance of the generic result type.</returns>
    public static TResult RunSync<TResult>(Func<Task<TResult>> func)
    {
        var cultureUi = CultureInfo.CurrentUICulture;
        var culture = CultureInfo.CurrentCulture;

        Task<TResult> task = _myTaskFactory.StartNew(func).Unwrap();
        task.Wait(); // This will not block the calling thread

        // Preserve the culture settings
        CultureInfo.CurrentUICulture = cultureUi;
        CultureInfo.CurrentCulture = culture;

        return task.Result;
    }
}

