using System.Threading.Tasks;
using Azure.Messaging.EventHubs.Producer;
using Microsoft.Azure.Management.EventHub;
using Microsoft.Azure.Management.EventHub.Models;

namespace Energinet.DataHub.Core.FunctionApp.TestCommon.EventHub.ResourceProvider
{
    public class EventHubResource : IAsyncDisposable
    {
        private readonly string _eventHubConnectionString;
        private EventHubProducerClient _producerClient;

        public EventHubResource(string eventHubConnectionString)
        {
            _eventHubConnectionString = eventHubConnectionString;
        }

        public async Task SendMessagesAsync(List<string> messages)
        {
            if (_producerClient == null)
            {
                _producerClient = new EventHubProducerClient(_eventHubConnectionString);
            }

            try
            {
                using EventDataBatch eventBatch = await _producerClient.CreateBatchAsync();

                foreach (string message in messages)
                {
                    if (!eventBatch.TryAdd(new EventData(System.Text.Encoding.UTF8.GetBytes(message)))
                    {
                        // The message is too large to fit in the batch. Handle this scenario as per requirements.
                        throw new Exception("Message size exceeds the maximum batch size.");
                    }
                }

                await _producerClient.SendAsync(eventBatch);
            }
            catch (Exception ex)
            {
                // Handle any exceptions that may occur during the message sending process
                Console.WriteLine($"An error occurred while sending messages: {ex.Message}");
                // Log or handle the exception as per requirements
            }
        }

        public async ValueTask DisposeAsync()
        {
            if (_producerClient != null)
            {
                await _producerClient.DisposeAsync();
            }
        }
    }
}

