using System;
using System.Collections.Generic;

public class ComponentRegistry
{
    private static Dictionary<string, Type> components;

    public static void Init()
    {
        components = new Dictionary<string, Type>();
    }

    public static void Register(string name, Type type)
    {
        if (components == null)
            throw new InvalidOperationException("Init must be called before registering components!");

        components[name.ToLower()] = type;
    }

    public static Type Get(string name)
    {
        if (components == null)
            throw new InvalidOperationException("Init must be called before accessing component dictionary!");

        if (components.TryGetValue(name.ToLower(), out Type type))
        {
            return type;
        }
        else
        {
            throw new KeyNotFoundException($"Component with name '{name}' does not exist in the registry.");
        }
    }

    public static bool Exists(string name, out Type type)
    {
        if (components == null)
            throw new InvalidOperationException("Init must be called before accessing component dictionary!");
        else return components.TryGetValue(name.ToLower(), out type);
    }
}

