    private Dictionary<string, List<Action<string>>> _eventCallbacks;

    public EventHandler()
    {
        _eventCallbacks = new Dictionary<string, List<Action<string>>>();
    }

    /// <summary>
    /// Registers a callback function for the specified event.
    /// </summary>
    /// <param name="eventName">The name of the event.</param>
    /// <param name="callback">The callback function to be registered.</param>
    public void RegisterCallback(string eventName, Action<string> callback)
    {
        if (!_eventCallbacks.ContainsKey(eventName))
        {
            _eventCallbacks[eventName] = new List<Action<string>>();
        }
        _eventCallbacks[eventName].Add(callback);
    }

    /// <summary>
    /// Triggers the specified event, invoking all registered callbacks for that event.
    /// </summary>
    /// <param name="eventName">The name of the event to trigger.</param>
    /// <param name="arg">The argument to be passed to the callback functions.</param>
    public void TriggerEvent(string eventName, string arg)
    {
        if (_eventCallbacks.ContainsKey(eventName))
        {
            foreach (var callback in _eventCallbacks[eventName])
            {
                callback.Invoke(arg);
            }
        }
    }
}

