{
    public bool CaseInsensitiveStringCompare(string str1, string str2)
    {
        if (str1.Length != str2.Length)
        {
            return false;
        }

        for (int i = 0; i < str1.Length; i++)
        {
            if (ToLowerInvariant(str1[i]) != ToLowerInvariant(str2[i]))
            {
                return false;
            }
        }

        return true;
    }

    private char ToLowerInvariant(char c)
    {
        if (c >= 'A' && c <= 'Z')
        {
            return (char)(c + 32);
        }
        return c;
    }
}

