using System.Collections.Generic;
using System.Text;
using IniParser;
using IniParser.Model;

public class IniFileParser
{
    public Dictionary<string, Dictionary<string, string>> ParseIniFile(string filePath)
    {
        var parser = new FileIniDataParser();
        IniData parsedData = parser.ReadFile(filePath, Encoding.UTF8);

        Dictionary<string, Dictionary<string, string>> iniDictionary = new Dictionary<string, Dictionary<string, string>>();

        foreach (SectionData section in parsedData.Sections)
        {
            Dictionary<string, string> sectionDictionary = new Dictionary<string, string>();

            foreach (KeyData key in section.Keys)
            {
                sectionDictionary.Add(key.KeyName, key.Value);
            }

            iniDictionary.Add(section.SectionName, sectionDictionary);
        }

        return iniDictionary;
    }
}

