public class Lookup
{
    private Dictionary<string, object> keyValuePairs;

    public Lookup(params object[] keyValues)
    {
        if (keyValues.Length % 2 != 0)
        {
            throw new ArgumentException("Key-value pairs must be provided in pairs.");
        }

        keyValuePairs = new Dictionary<string, object>();

        for (int i = 0; i < keyValues.Length; i += 2)
        {
            string key = keyValues[i].ToString();
            object value = keyValues[i + 1];
            Add(key, value);
        }
    }

    public void Add(string key, object value)
    {
        if (keyValuePairs.ContainsKey(key))
        {
            throw new ArgumentException($"Key '{key}' already exists in the lookup.");
        }
        keyValuePairs.Add(key, value);
    }

    public object Get(string key)
