    if (bitmaps.Length != placementPoints.Length)
    {
        throw new Exception("The amount of items in bitmaps and placementPoints must be the same!");
    }

    Bitmap finalBitmap = new Bitmap(1, 1, PixelFormat.Format32bppArgb);
    int maxWidth = 0;
    int maxHeight = 0;

    // Calculate the size of the final bitmap based on the placement points
    for (int i = 0; i < bitmaps.Length; i++)
    {
        maxWidth = Math.Max(maxWidth, placementPoints[i].X + bitmaps[i].Width);
        maxHeight = Math.Max(maxHeight, placementPoints[i].Y + bitmaps[i].Height);
    }

    finalBitmap = new Bitmap(maxWidth, maxHeight, PixelFormat.Format32bppArgb);
    finalBitmap.MakeTransparent();

    using (Graphics g = Graphics.FromImage(finalBitmap))
    {
        for (int i = 0; i < bitmaps.Length; i++)
        {
            g.DrawImage(bitmaps[i], placementPoints[i]);
        }
    }

    return finalBitmap;
}

