public interface IServiceContainer
{
    void Register<TService, TImplementation>(TImplementation implementation) where TImplementation : TService;
    TService Resolve<TService>();
}

public class ServiceContainer : IServiceContainer
{
    private readonly Dictionary<Type, object> _serviceImplementations = new Dictionary<Type, object>();

    public void Register<TService, TImplementation>(TImplementation implementation) where TImplementation : TService
    {
        var serviceType = typeof(TService);
        if (_serviceImplementations.ContainsKey(serviceType))
        {
            throw new InvalidOperationException($"Service of type {serviceType.Name} is already registered.");
        }
        _serviceImplementations[serviceType] = implementation;
    }

    public TService Resolve<TService>()
    {
        var serviceType = typeof(TService);
        if (!_serviceImplementations.ContainsKey(serviceType))
        {
            throw new InvalidOperationException($"Service of type {serviceType.Name} is not registered.");
        }
        return (TService)_serviceImplementations[serviceType];
    }
}

