        Random rng = new Random();
        int n = cardList.Count;
        while (n > 1)
        {
            n--;
            int k = rng.Next(n + 1);
            Card temp = cardList[k];
            cardList[k] = cardList[n];
            cardList[n] = temp;
        }
        deck = new Stack<Card>(cardList);
