            DateTime dateTimeValue = _dateTime.Value;
            string formattedString = "";
            int index = 0;

            while (index < customFormat.Length)
            {
                if (customFormat[index] == 'y')
                {
                    int year = dateTimeValue.Year;
                    formattedString += year.ToString();
                    index += 2;
                }
                else if (customFormat[index] == 'M')
                {
                    int month = dateTimeValue.Month;
                    formattedString += month.ToString("00");
                    index += 2;
                }
                else if (customFormat[index] == 'd')
                {
                    int day = dateTimeValue.Day;
                    formattedString += day.ToString("00");
                    index += 2;
                }
                else if (customFormat[index] == 'h')
                {
                    int hour = dateTimeValue.Hour;
                    formattedString += hour.ToString("00");
                    index += 2;
                }
                else if (customFormat[index] == 'm')
                {
                    int minute = dateTimeValue.Minute;
                    formattedString += minute.ToString("00");
                    index += 2;
                }
                else if (customFormat[index] == 's')
                {
                    int second = dateTimeValue.Second;
                    formattedString += second.ToString("00");
                    index += 2;
                }
                else
                {
                    formattedString += customFormat[index];
                    index++;
                }
            }

            return formattedString;
        }
    }
}

