            var lineLength = 0;

            foreach (var word in words)
            {
                if (lineLength + word.Length > columnNumber)
                {
                    result.Append(Environment.NewLine);
                    lineLength = 0;
                }
                result.Append(word);
                result.Append(' ');
                lineLength += word.Length + 1;
            }

