        {
            if (data == null)
                throw new ArgumentNullException(nameof(data));

            using (var memoryStream = new MemoryStream(data))
            {
                if (_binaryFormatter == null)
                    _binaryFormatter = new BinaryFormatter();

                return (T)_binaryFormatter.Deserialize(memoryStream);
            }
        }
    }
}

