static void FillDigits64FixedLength(ulong number, char[] buffer, ref int length)
{
    const uint kTen7 = 10000000;
    // For efficiency cut the number into 3 uint32_t parts, and print those.
    uint part2 = (uint)(number % kTen7);
    number /= kTen7;
    uint part1 = (uint)(number % kTen7);
    uint part0 = (uint)(number / kTen7);

    // Convert each part into a string and store in the buffer
    string part0Str = part0.ToString("D7");
    string part1Str = part1.ToString("D7");
    string part2Str = part2.ToString("D7");

    // Copy the string representations into the buffer
    part0Str.CopyTo(0, buffer, length, part0Str.Length);
    length += part0Str.Length;
    part1Str.CopyTo(0, buffer, length, part1Str.Length);
    length += part1Str.Length;
    part2Str.CopyTo(0, buffer, length, part2Str.Length);
    length += part2Str.Length;
}

