public bool ContainsHiddenChain(string input)
{
    int n = input.Length;
    for (int len = 1; len <= n / 2; len++) {
        string pattern = input.Substring(0, len);
        bool isHiddenChain = true;
        for (int i = len; i <= n - len; i += len) {
            if (input.Substring(i, len) != pattern) {
                isHiddenChain = false;
                break;
            }
        }
        if (isHiddenChain) {
            return true;
        }
    }
    return false;
}

