public static class EarthConstants
{
    public const double EarthCircumference = 40075000; // in meters
}

public static class GeoCalculator
{
    public static double DistLongitude(double a, double b, double latitudeY)
    {
        return ((a - b) * EarthConstants.EarthCircumference * Math.Cos(latitudeY * Units.deg2rad)) / 360.0;
    }

    public static BoundingBox LatLonBounds(double latitudeY, double longitudeX, double radiusM)
    {
        double radiusY = (radiusM * 360) / EarthConstants.EarthCircumference;
        double radiusX = (radiusM * 360) / (EarthConstants.EarthCircumference * Math.Cos(latitudeY * Units.deg2rad));

        BoundingBox boundingBox = new BoundingBox
        {
            MinLatitude = latitudeY - radiusY,
            MaxLatitude = latitudeY + radiusY,
            MinLongitude = longitudeX - radiusX,
            MaxLongitude = longitudeX + radiusX
        };

        return boundingBox;
    }
}

